import logging

from taf.nms.netact.command import CommandBuilder

logger = logging.getLogger(__name__)
logger.addHandler(logging.NullHandler())


class Monitor:
    NASDA_SCRIPT_PATH = '/opt/oss/bin/nasdaclimx.sh'

    def __init__(self, ssh_was_node):
        self.ssh_was_node = ssh_was_node

    def delete_object_from_monitor(self, dist_name):
        """
        Delete managed object from Monitor application using `nasdaclimx.sh`.

        :param string dist_name: Specifies the distinguished name of the managed object,
            e.g., ``PLMN-PLMN/MRBTS-12345``
        :return: command result
        :rtype: bool
        """
        app = '-objmgr'
        command = CommandBuilder(
            executable=f'{self.NASDA_SCRIPT_PATH} {app}',
            options={'-remove': dist_name}
        ).text

        with self.ssh_was_node as ssh:
            output = ssh.execute_command(command, ignore_stderr=True, ignore_rc=True).stdout

        logger.debug(output)
        return 'Operation finished successfully' in output

    def get_objects_from_monitor(self, mo_class='MR', timeout=300):
        """
        Get managed objects for a specific class from Monitor application using `nasdaclimx.sh`.

        :param string mo_class: Specifies the class of the managed object, e.g., ``MRBTS`` or ``FHGW``
        :param int timeout: Timeout for executing operation
        :return: Managed objects
        :rtype: list
        """
        app = '-objmgr'
        command = CommandBuilder(
            executable=f'{self.NASDA_SCRIPT_PATH} {app}',
            options={'-search': f'any::{mo_class}'}
        ).text

        with self.ssh_was_node as ssh:
            output = ssh.execute_command(command, timeout=timeout).stdout

        logger.debug(output)
        exclusions = [
            '[DEBUG]',
            'ObjectManager:'
        ]
        return [line for line in output.splitlines() if not self._skip_line(line, exclusions)]

    @staticmethod
    def _skip_line(line, exclusions):
        return any(e.lower() in line.lower() for e in exclusions)
